import{_ as a,o as e,c as o,a1 as r}from"./chunks/framework.Dvq7PH7Q.js";const u=JSON.parse('{"title":"博客上线的第一天","description":"折腾了一整天，博客终于上线了，记一笔流水账。","frontmatter":{"title":"博客上线的第一天","date":"2026-08-19T00:00:00.000Z","tags":["日记"],"description":"折腾了一整天，博客终于上线了，记一笔流水账。"},"headers":[],"relativePath":"posts/diary-20260819.md","filePath":"posts/diary-20260819.md","lastUpdated":null}'),s={name:"posts/diary-20260819.md"};function i(p,t,l,n,d,_){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="博客上线的第一天" tabindex="-1">博客上线的第一天 <a class="header-anchor" href="#博客上线的第一天" aria-label="Permalink to &quot;博客上线的第一天&quot;">​</a></h1><p>折腾了一整天，博客终于上线了。</p><p>早上还在纠结用哪个框架，晚上就已经能看到自己的小角落了——这种感觉挺奇妙的。</p><p>今天做的事：</p><ul><li>选了 VitePress，写了主题组件，调了暖橙配色；</li><li>把「成的小屋」的牌子挂了上去，头像也换成了自己的照片；</li><li>经历了几轮&quot;主页空白&quot;和&quot;推不上去&quot;的折腾，好在都解决了。</li></ul><p>晚上坐在电脑前，看着首页那句 <strong>休息也是工作的一部分</strong>，觉得今天过得挺值。</p><p>以后就在这里写写代码、记记生活。第一篇，就这么开始吧。</p>',7)])])}const m=a(s,[["render",i]]);export{u as __pageData,m as default};
